package main

import (
	"fmt"
	"regexp"
)

func isValidFilename(filename string) bool {
	// Regular expression to allow only alphanumeric characters, dashes, underscores, and dots
	re := regexp.MustCompile(`^[a-zA-Z0-9._-]+$`)
	return re.MatchString(filename)
}

func main() {
	fmt.Println(isValidFilename("peters_mixtape.mp3")) // Expected: true
	fmt.Println(isValidFilename("../evil.mp3"))        // Expected: false
	fmt.Println(isValidFilename("nice_song!.mp3"))     // Expected: false
